#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<array<int, 3>> a(n);
    vector<int> ys;
    for (int i = 0; i < n; i++) {
        cin >> a[i][0] >> a[i][1];
        a[i][2] = i + 1;
        ys.push_back(a[i][1]);
    }
    sort(ys.begin(), ys.end());
    for (auto &p : a)
        p[1] = lower_bound(ys.begin(), ys.end(), p[1]) - ys.begin();
    sort(a.begin(), a.end());
    vector<long long> diff(n + 2);
    for (int l = 0; l < n; l++) {
        vector<int> up(n + 1, n + 1), down(n + 1, n + 1);
        int y = a[l][1];
        for (int r = l + 1; r < n; r++) {
            int dy = a[r][1] - y, k = abs(dy);
            auto &b = dy > 0 ? up : down;
            int first = n + 1;
            for (int q = k - 1; q; q -= q & -q)
                first = min(first, b[q]);
            int L = max(a[l][2], a[r][2]), R = first - 1;
            if (L <= R) {
                diff[L]++;
                diff[R + 1]--;
            }
            for (int q = k; q <= n; q += q & -q)
                b[q] = min(b[q], a[r][2]);
        }
    }
    long long cur = 0, A = 0, B = 0;
    for (int i = 1; i <= n; i++) {
        cur += diff[i];
        (i % 2 ? A : B) += cur;
    }
    cout << A << ' ' << B << '\n';
}

