    function<void(int, int, int)> f = [&](int r, int c, int k) {
        int b = p[r + k][c + k] - p[r][c + k] - p[r + k][c] + p[r][c];
        if (b == 0 || b == k * k) {
            out.push_back(b ? 'b' : 'w');
            return;
        }
        out.push_back('g');
        int h = k / 2;
        f(r, c + h, h);
        f(r, c, h);
        f(r + h, c, h);
        f(r + h, c + h, h);
    };
    f(0, 0, n);
    for (int i = 0; i < (int)out.size(); i++) {
        if (i)
            cout << ' ';
        cout << out[i];
    }
    cout << '\n';
