#include <bits/stdc++.h>
using namespace std;
struct Dinic {
    struct E {
        int v, rev;
        long long c;
    };
    vector<vector<E>> g;
    vector<int> d, it;
    Dinic(int n) : g(n), d(n), it(n) {
    }
    void add(int u, int v, long long c) {
        E a{v, (int)g[v].size(), c}, b{u, (int)g[u].size(), 0};
        g[u].push_back(a);
        g[v].push_back(b);
    }
    long long dfs(int u, int t, long long f) {
        if (u == t)
            return f;
        for (int &i = it[u]; i < (int)g[u].size(); i++) {
            E &e = g[u][i];
            if (e.c && d[e.v] == d[u] + 1) {
                long long z = dfs(e.v, t, min(f, e.c));
                if (z) {
                    e.c -= z;
                    g[e.v][e.rev].c += z;
                    return z;
                }
            }
        }
        return 0;
    }
    long long flow(int s, int t) {
        long long ans = 0;
        while (1) {
            fill(d.begin(), d.end(), -1);
            queue<int> q;
            q.push(s);
            d[s] = 0;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (auto e : g[u])
                    if (e.c && d[e.v] < 0) {
                        d[e.v] = d[u] + 1;
                        q.push(e.v);
                    }
            }
            if (d[t] < 0)
                return ans;
            fill(it.begin(), it.end(), 0);
            while (long long z = dfs(s, t, LLONG_MAX))
                ans += z;
        }
    }
};
int main() {
    int n, m;
    cin >> n >> m;
    Dinic f(n + 2);
    long long b = 0, x;
    for (int i = 0; i < n; i++) {
        cin >> x;
        b += x;
        f.add(n, i, x);
    }
    for (int i = 0; i < n; i++) {
        cin >> x;
        b += x;
        f.add(i, n + 1, x);
    }
    while (m--) {
        int u, v, a;
        cin >> u >> v >> a;
        u--;
        v--;
        b += a;
        f.add(u, v, a);
        f.add(v, u, a);
    }
    cout << b - f.flow(n, n + 1) << '\n';
}

