    while (W < m)
        W *= 2;
    vector<int> seg(2 * W, -1);
    for (int i = 0; i < m; i++) {
        x[i] = p[ord[i]];
        seg[W + i] = h[ord[i]];
    }
    for (int i = W - 1; i; i--)
        seg[i] = max(seg[2 * i], seg[2 * i + 1]);
    function<int(int, int, int, int, int, int, bool)> find =
        [&](int u, int l, int r, int a, int b, int H, bool rev) {
            if (r <= a || b <= l || seg[u] < H)
                return -1;
            if (r - l == 1)
                return l;
            int mid = (l + r) / 2, v;
            if (rev) {
                v = find(2 * u + 1, mid, r, a, b, H, rev);
                if (v < 0)
                    v = find(2 * u, l, mid, a, b, H, rev);
            } else {
                v = find(2 * u, l, mid, a, b, H, rev);
                if (v < 0)
                    v = find(2 * u + 1, mid, r, a, b, H, rev);
            }
            return v;
        };
    while (n--) {
        int k;
        cin >> k;
        vector<int> a(k);
        int H = 0;
        for (int &z : a) {
            int id;
            cin >> id;
            z = p[id];
            H = max(H, h[id]);
        }
