        int med = a[k / 2], j = lower_bound(x.begin(), x.end(), med) - x.begin();
        long long ans = LLONG_MAX;
        for (int v : {find(1, 0, W, 0, j + 1, H, true), find(1, 0, W, j, m, H, false)})
            if (v >= 0) {
                long long z = 0;
                for (int t : a)
                    z += abs(1LL * t - x[v]);
                ans = min(ans, z);
