#include <bits/stdc++.h>
using namespace std;
#include <boost/multiprecision/cpp_int.hpp>
using boost::multiprecision::cpp_int;
cpp_int G(cpp_int a, cpp_int b) {
    while (b != 0) {
        cpp_int r = a % b;
        a = b;
        b = r;
    }
    return a;
}
struct E {
    int u, v, q, p, id;
};
int main() {
    int n, m;
    cin >> n >> m;
    vector<E> e(m);
    for (int i = 0; i < m; i++) {
        auto &x = e[i];
        cin >> x.u >> x.v >> x.q >> x.p;
        x.id = i;
    }
    vector<int> ord(m), par(n), sz(n, 1), used(m);
    iota(ord.begin(), ord.end(), 0);
    iota(par.begin(), par.end(), 0);
    auto lessrat = [&](int i, int j) {
        return 1LL * e[i].q * e[j].p < 1LL * e[j].q * e[i].p;
    };
    sort(ord.begin(), ord.end(), [&](int i, int j) { return lessrat(j, i); });
    auto find = [&](int x) {
        while (x != par[x])
            x = par[x] = par[par[x]];
        return x;
    };
    vector<vector<pair<int, int>>> g(n);
    cpp_int num = 1, den = 1;
    for (int k : ord) {
        auto x = e[k];
        int a = find(x.u), b = find(x.v);
        if (a == b)
            continue;
        if (sz[a] < sz[b])
            swap(a, b);
        par[b] = a;
        sz[a] += sz[b];
        used[k] = 1;
        g[x.u].push_back({x.v, k});
        g[x.v].push_back({x.u, k});
        num *= x.q;
        den *= x.p;
        cpp_int z = G(num, den);
        num /= z;
        den /= z;
    }
    vector<vector<int>> mn(n, vector<int>(n, -1));
    for (int s = 0; s < n; s++) {
        vector<pair<int, int>> st = {{s, -1}};
        while (!st.empty()) {
            auto [u, p] = st.back();
            st.pop_back();
            for (auto [v, k] : g[u])
                if (v != p) {
                    int z = mn[s][u];
