struct RangeMax {
    int n;
    vector<int> v, lazy;
    RangeMax(int m) : n(m), v(4 * m + 8), lazy(4 * m + 8) {
    }
    void add(int p, int l, int r, int a, int b, int x) {
        if (a <= l && r <= b) {
            v[p] += x;
            lazy[p] += x;
            return;
        }
        int h = (l + r) / 2;
        if (a < h)
            add(2 * p, l, h, a, b, x);
        if (b > h)
            add(2 * p + 1, h, r, a, b, x);
        v[p] = lazy[p] + max(v[2 * p], v[2 * p + 1]);
    }
    void add(int a, int b, int x) {
        if (a < b)
            add(1, 0, n, a, b, x);
    }
};

