                self.v[p] += x
                self.lazy[p] += x
                return
            h = (l + r) // 2
            if a < h:
                rec(2 * p, l, h)
            if b > h:
                rec(2 * p + 1, h, r)
            self.v[p] = self.lazy[p] + max(self.v[2 * p], self.v[2 * p + 1])

