        auto b = move(st.back());
        st.pop_back();
        auto a = move(st.back());
        st.pop_back();
        vector<P> z;
        for (auto [w1, h1] : a)
            for (auto [w2, h2] : b)
                z.push_back(t == "H" ? P{max(w1, w2), h1 + h2}
                                     : P{w1 + w2, max(h1, h2)});
        st.push_back(prune(z));
    }
    long long ans = LLONG_MAX;
    for (auto [w, h] : st.back())
        ans = min(ans, 1LL * w * h);
    cout << ans << '\n';
}

