using namespace std;
struct G {
    long long mx, base, best;
};
long long upd(vector<G> &s, long long x, long long z) {
    while (!s.empty() && s.back().mx <= x) {
        z = min(z, s.back().base);
        s.pop_back();
    }
    long long ans = x + z;
    if (!s.empty())
        ans = min(ans, s.back().best);
    s.push_back({x, z, ans});
    return ans;
}
int main() {
