    long long B = accumulate(b.begin(), b.end(), 0LL),
              W = accumulate(w.begin(), w.end(), 0LL), sb = 0, sw = 0, db = 0, dw = 0,
              ans = LLONG_MAX;
    vector<G> bs, ws;
    for (int i = 0; i < n; i++) {
        ans = min({ans, db + B - sb, dw + W - sw});
        long long nb = upd(ws, sw + w[i] + t[i], dw - sw),
                  nw = upd(bs, sb + b[i] + t[i], db - sb);
