#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int n, P;
vector<vector<int>> A, B;
vector<array<int, 3>> answer;
int power(int a, int b) {
    ll r = 1;
    for (; b; b >>= 1, a = ll(a) * a % P)
        if (b & 1)
            r = r * a % P;
    return int(r);
}
template <int T> void run() {
    using Vec = array<int, T>;
    struct Row {
        int i;
        Vec z;
    };
    vector<Vec> v(n);
    vector<pair<int, int>> inv(n, {-1, 0});
    random_device rng;
    uniform_int_distribution<int> dist(0, P - 1);
    for (int j = 0; j < n; j++)
        for (int t = 0; t < T; t++) {
            v[j][t] = dist(rng);
            if (inv[j].first < 0 && v[j][t])
                inv[j] = {t, power(v[j][t], P - 2)};
        }
    auto nonzero = [](const Vec &z) {
        for (int x : z)
            if (x)
                return true;
        return false;
    };
    auto projectB = [&](int l, int r) {
        vector<Vec> w(n);
        for (int k = 0; k < n; k++) {
            array<ll, T> z{};
            for (int j = l; j < r; j++)
                for (int t = 0; t < T; t++)
                    z[t] += ll(B[k][j]) * v[j][t];
            for (int t = 0; t < T; t++)
                w[k][t] = z[t] % P;
        }
        return w;
    };
    auto projectA = [&](int i, const vector<Vec> &w) {
        array<ll, T> z{};
        for (int k = 0; k < n; k++)
            for (int t = 0; t < T; t++)
                z[t] += ll(A[i][k]) * w[k][t];
        Vec result;
        for (int t = 0; t < T; t++)
            result[t] = z[t] % P;
        return result;
    };
    function<void(int, int, const vector<Vec> &, const vector<Row> &)> solve;
    solve = [&](int l, int r, const vector<Vec> &w, const vector<Row> &rows) {
        if (rows.empty())
            return;
        if (r - l == 1) {
            auto [t, u] = inv[l];
            if (t < 0)
                return;
            for (auto &row : rows) {
                int value = ll(row.z[t]) * u % P;
                if (value)
                    answer.push_back({row.i + 1, l + 1, value});
            }
            return;
        }
        int mid = (l + r) / 2;
        auto lw = projectB(l, mid), rw = w;
        for (int k = 0; k < n; k++)
            for (int t = 0; t < T; t++) {
                rw[k][t] -= lw[k][t];
                if (rw[k][t] < 0)
                    rw[k][t] += P;
            }
        vector<Row> left, right;
        for (auto &row : rows) {
            Vec a = projectA(row.i, lw), b;
            for (int t = 0; t < T; t++) {
                b[t] = row.z[t] - a[t];
                if (b[t] < 0)
                    b[t] += P;
            }
            if (nonzero(a))
                left.push_back({row.i, a});
            if (nonzero(b))
                right.push_back({row.i, b});
        }
        solve(l, mid, lw, left);
        solve(mid, r, rw, right);
    };
    auto w = projectB(0, n);
    vector<Row> rows;
    for (int i = 0; i < n; i++) {
        auto z = projectA(i, w);
        if (nonzero(z))
            rows.push_back({i, z});
    }
    solve(0, n, w, rows);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int sub;
    cin >> sub >> n >> P;
    A.assign(n, vector<int>(n));
    B = A;
    for (auto &row : A)
        for (int &x : row)
            cin >> x;
    for (auto &row : B)
        for (int &x : row)
            cin >> x;
    int T = ceil(42 / log(double(P)));
    switch (T) {
    case 3:
        run<3>();
        break;
    case 4:
        run<4>();
        break;
    case 5:
        run<5>();
        break;
    case 6:
        run<6>();
        break;
    case 7:
        run<7>();
        break;
    case 8:
        run<8>();
        break;
    case 9:
        run<9>();
        break;
    case 10:
        run<10>();
        break;
    case 11:
        run<11>();
        break;
    case 12:
        run<12>();
        break;
    }
    sort(answer.begin(), answer.end());
    for (auto [i, j, x] : answer)
        cout << i << ' ' << j << ' ' << x << '\n';
}

#include <bits/stdc++.h>
using namespace std;
struct RangeMax {
    int n;
    vector<int> v, lazy;
    RangeMax(int m) : n(m), v(4 * m + 8), lazy(4 * m + 8) {
    }
    void add(int p, int l, int r, int a, int b, int x) {
        if (a <= l && r <= b) {
            v[p] += x;
            lazy[p] += x;
            return;
        }
        int h = (l + r) / 2;
        if (a < h)
            add(2 * p, l, h, a, b, x);
        if (b > h)
            add(2 * p + 1, h, r, a, b, x);
        v[p] = lazy[p] + max(v[2 * p], v[2 * p + 1]);
    }
    void add(int a, int b, int x) {
        if (a < b)
            add(1, 0, n, a, b, x);
    }
};

