    for (int z : a) {
        int t = z & X;
        if (!t)
            p[0]++;
        else if (t == X && z != X)
            p[1]++;
        else if (t == z && z != X)
            p[2]++;
        else if (t != X && t != z)
            p[3]++;
    }
    auto ok = [&](int x, int y) {
        int t = x & y;
        return !t || t == x || t == y;
    };
    int ways = 0;
    for (int A = (X - 1) & X; A; A = (A - 1) & X) {
        int B = X ^ A;
        bool good = 1;
        for (int z : a)
            if (!ok(A, z) || !ok(B, z)) {
                good = 0;
                break;
            }
        ways += good;
    }
    cout << p[0] << ' ' << p[1] << ' ' << p[2] << ' ' << p[3] << ' ' << ways << '\n';
}

