#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, src;
    long long water;
    cin >> n >> src >> water;
    vector<long long> h(n);
    for (auto &x : h)
        cin >> x;
    int m = n - 1, N = 2 * m - 1;
    vector<int> L(N, -1), R(N, -1), lo(N), hi(N), st;
    vector<long long> height(N), fill(N, -1);
    for (int i = 0; i < m; i++)
        lo[i] = i, hi[i] = i + 1;
    for (int j = 1; j < n - 1; j++) {
        int u = m + j - 1, last = -1;
        height[u] = h[j];
        while (!st.empty() && height[st.back()] < h[j]) {
            last = st.back();
            st.pop_back();
        }
        L[u] = last;
        if (!st.empty())
            R[st.back()] = u;
        st.push_back(u);
    }
    int root = st[0];
    vector<int> order = {root};
    for (int k = 0; k < (int)order.size(); k++) {
        int u = order[k], j = u - m + 1;
        if (L[u] < 0)
            L[u] = j - 1;
        if (R[u] < 0)
            R[u] = j;
        if (L[u] >= m)
            order.push_back(L[u]);
        if (R[u] >= m)
            order.push_back(R[u]);
    }
    for (int k = order.size() - 1; k >= 0; k--) {
        int u = order[k];
        lo[u] = lo[L[u]];
        hi[u] = hi[R[u]];
    }
    struct F {
        int u, s, phase, first, other;
        long long cap, v;
    };
    vector<F> stack = {{root, src, 0, 0, 0, min(h[0], h[n - 1]), water}};
    long long ret = 0;
    while (!stack.empty()) {
        auto &f = stack.back();
        int u = f.u;
        long long cnt = hi[u] - lo[u];
        if (f.phase == 0) {
            if (f.v >= f.cap * cnt) {
                fill[u] = f.cap;
                ret = f.v - f.cap * cnt;
                stack.pop_back();
                continue;
            }
            if (u < m) {
                fill[u] = f.v;
                ret = 0;
                stack.pop_back();
                continue;
            }
            f.first = f.s < hi[L[u]] ? L[u] : R[u];
            f.other = f.first == L[u] ? R[u] : L[u];
            f.phase = 1;
            stack.push_back({f.first, f.s, 0, 0, 0, height[u], f.v});
        } else if (f.phase == 1) {
            if (!ret) {
                stack.pop_back();
                continue;
            }
            f.phase = 2;
            int s = f.other == L[u] ? hi[f.other] - 1 : lo[f.other];
            stack.push_back({f.other, s, 0, 0, 0, height[u], ret});
        } else {
            if (ret)
                fill[u] = height[u] + ret / cnt;
            ret = 0;
            stack.pop_back();
        }
    }
    vector<long long> ans(m);
    vector<int> q = {root};
    while (!q.empty()) {
        int u = q.back();
        q.pop_back();
        if (fill[u] >= 0) {
            for (int i = lo[u]; i < hi[u]; i++)
                ans[i] = fill[u];
        } else if (u >= m) {
            q.push_back(L[u]);
            q.push_back(R[u]);
        }
    }
    for (int i = 0; i < m; i++) {
        if (i)
            cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
}

