    int n, K;
    cin >> n >> K;
    vector<vector<pair<int, int>>> g(n);
    for (int i = 1, u, v, w; i < n; i++) {
        cin >> u >> v >> w;
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }
    int L = 1;
    while ((1 << L) <= n)
        L++;
    vector<vector<int>> up(L, vector<int>(n));
    vector<int> dep(n), tin(n);
    vector<long long> d(n);
    vector<array<int, 2>> st = {{0, -1}};
    int timer = 0;
    while (!st.empty()) {
        auto [u, p] = st.back();
        st.pop_back();
        tin[u] = timer++;
        for (auto [v, w] : g[u])
            if (v != p) {
                up[0][v] = u;
                dep[v] = dep[u] + 1;
                d[v] = d[u] + w;
                st.push_back({v, u});
            }
    }
    for (int j = 1; j < L; j++)
        for (int v = 0; v < n; v++)
            up[j][v] = up[j - 1][up[j - 1][v]];
    auto dist = [&](int a, int b) {
        long long z = d[a] + d[b];
        if (dep[a] < dep[b])
            swap(a, b);
        int diff = dep[a] - dep[b];
        for (int j = 0; j < L; j++)
            if (diff >> j & 1)
                a = up[j][a];
        if (a != b) {
            for (int j = L - 1; j >= 0; j--)
                if (up[j][a] != up[j][b]) {
                    a = up[j][a];
                    b = up[j][b];
                }
            a = up[0][a];
        }
        return z - 2 * d[a];
    };
    long long ans = 0;
    while (K--) {
        int k;
        cin >> k;
        vector<int> a(k);
        for (int &x : a)
            cin >> x;
        sort(a.begin(), a.end(), [&](int x, int y) { return tin[x] < tin[y]; });
        long long cycle = 0;
        for (int i = 0; i < k; i++)
            cycle += dist(a[i], a[(i + 1) % k]);
        int u = a[0];
        for (int v : a)
            if (dist(a[0], v) > dist(a[0], u))
                u = v;
        long long D = 0;
        for (int v : a)
            D = max(D, dist(u, v));
        ans += cycle - D;
    }
    cout << ans << '\n';
}

