#include <bits/stdc++.h>
using namespace std;
struct E {
    int x, y, z, d;
};
int main() {
    int n;
    cin >> n;
    vector<E> e;
    vector<int> y;
    for (int i = 0, a, b, c, d; i < n; i++) {
        cin >> a >> b >> c >> d;
        if (a == c || b == d)
            continue;
        e.push_back({a, b, d, 1});
        e.push_back({c, b, d, -1});
        y.push_back(b);
        y.push_back(d);
    }
    if (e.empty()) {
        cout << 0 << '\n';
        return 0;
    }
    sort(y.begin(), y.end());
    y.erase(unique(y.begin(), y.end()), y.end());
    int m = y.size() - 1;
    vector<int> cnt(4 * m + 4);
    vector<long long> len(4 * m + 4);
    function<void(int, int, int, int, int, int)> upd = [&](int p, int l, int r, int a,
                                                           int b, int d) {
        if (a <= l && r <= b)
            cnt[p] += d;
        else {
            int h = (l + r) / 2;
            if (a < h)
                upd(p * 2, l, h, a, b, d);
            if (b > h)
                upd(p * 2 + 1, h, r, a, b, d);
        }
        len[p] = cnt[p] ? y[r] - y[l] : (r - l == 1 ? 0 : len[p * 2] + len[p * 2 + 1]);
    };
    sort(e.begin(), e.end(), [](E a, E b) { return a.x < b.x; });
    long long ans = 0;
    int last = e[0].x;
    for (auto a : e) {
        ans += 1LL * (a.x - last) * len[1];
        int l = lower_bound(y.begin(), y.end(), a.y) - y.begin(),
            r = lower_bound(y.begin(), y.end(), a.z) - y.begin();
        upd(1, 0, m, l, r, a.d);
        last = a.x;
    }
    cout << ans << '\n';
}
